-- TORVO V2 PRODUCT PROMOTIONS + POPULAR ITEMS
create table if not exists product_promotions(id uuid primary key default gen_random_uuid(),product_id uuid not null references catalog_items(id),title text not null,caption text not null default '',image_url text,target text not null default 'both' check(target in('website','dealer_app','both')),active boolean not null default true,starts_at timestamptz not null default now(),ends_at timestamptz,sort_order int not null default 100,created_by uuid references app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists product_popularity(product_id uuid primary key references catalog_items(id),manual_featured boolean not null default false,manual_rank int,view_count bigint not null default 0,enquiry_count bigint not null default 0,order_count bigint not null default 0,updated_at timestamptz not null default now());
alter table product_promotions enable row level security;alter table product_popularity enable row level security;revoke all on product_promotions,product_popularity from anon,authenticated;
create or replace function public_active_product_promotions(p_target text default 'website') returns table(product_id uuid,title text,caption text,image_url text) language plpgsql security definer set search_path=public as $$declare t text:=lower(btrim(coalesce(p_target,'website')));begin if t not in('website','dealer_app') then raise exception 'INVALID PROMOTION TARGET';end if;return query select p.product_id,p.title,p.caption,p.image_url from product_promotions p join catalog_items x on x.id=p.product_id where p.active=true and x.active=true and p.starts_at<=now() and(p.ends_at is null or p.ends_at>now())and(p.target='both'or p.target=t)order by p.sort_order,p.created_at desc limit 20;end$$;
drop function if exists public_popular_products(int);
create function public_popular_products(p_limit int default 12) returns setof jsonb language sql security definer set search_path=public as $$select jsonb_build_object('id',x.id,'product_id',x.id,'item_code',to_jsonb(x)->>'item_code','name',to_jsonb(x)->>'name','item_type',to_jsonb(x)->>'item_type','brand',to_jsonb(x)->>'brand','category',to_jsonb(x)->>'category','model',to_jsonb(x)->>'model','image_url',to_jsonb(x)->>'image_url') from catalog_items x left join product_popularity s on s.product_id=x.id where x.active=true order by coalesce(s.manual_featured,false) desc,coalesce(s.manual_rank,999999),coalesce(s.order_count,0) desc,coalesce(s.enquiry_count,0) desc,coalesce(s.view_count,0) desc,x.updated_at desc limit least(greatest(coalesce(p_limit,12),1),30)$$;
create or replace function admin_save_product_promotion(p_id uuid,p_product_id uuid,p_title text,p_caption text,p_image_url text,p_target text,p_active boolean,p_starts_at timestamptz,p_ends_at timestamptz,p_sort_order int,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$declare u app_users%rowtype;rid uuid:=coalesce(p_id,gen_random_uuid());t text:=lower(btrim(coalesce(p_target,'')));ttl text:=upper(btrim(coalesce(p_title,'')));cap text:=btrim(coalesce(p_caption,''));img text:=nullif(btrim(coalesce(p_image_url,'')),'');rsn text:=upper(btrim(coalesce(p_reason,'')));st timestamptz:=coalesce(p_starts_at,now());begin select * into u from app_users where auth_user_id=auth.uid() and active=true;if u.id is null or u.role not in('owner','admin')then raise exception 'OWNER OR ADMIN REQUIRED';end if;if p_product_id is null then raise exception 'PRODUCT REQUIRED';end if;if length(ttl)<2 or length(ttl)>120 then raise exception 'PROMOTION TITLE MUST BE 2 TO 120 CHARACTERS';end if;if length(cap)>500 then raise exception 'PROMOTION CAPTION MUST BE 500 CHARACTERS OR LESS';end if;if img is not null and length(img)>1000 then raise exception 'PROMOTION IMAGE URL MUST BE 1000 CHARACTERS OR LESS';end if;if length(rsn)<3 or length(rsn)>500 then raise exception 'CHANGE REASON MUST BE 3 TO 500 CHARACTERS';end if;if t not in('website','dealer_app','both')then raise exception 'INVALID PROMOTION TARGET';end if;if p_sort_order is null or p_sort_order<0 or p_sort_order>100000 then raise exception 'INVALID PROMOTION SORT ORDER';end if;if p_ends_at is not null and p_ends_at<=st then raise exception 'END TIME MUST BE AFTER START TIME';end if;if not exists(select 1 from catalog_items where id=p_product_id and active=true)then raise exception 'ACTIVE PRODUCT REQUIRED';end if;insert into product_promotions(id,product_id,title,caption,image_url,target,active,starts_at,ends_at,sort_order,created_by)values(rid,p_product_id,ttl,cap,img,t,coalesce(p_active,true),st,p_ends_at,p_sort_order,u.id)on conflict(id)do update set product_id=excluded.product_id,title=excluded.title,caption=excluded.caption,image_url=excluded.image_url,target=excluded.target,active=excluded.active,starts_at=excluded.starts_at,ends_at=excluded.ends_at,sort_order=excluded.sort_order,updated_at=now();insert into audit_log(actor_id,action,entity_type,entity_id,details)values(u.id,'PRODUCT_PROMOTION_SAVED','PRODUCT_PROMOTION',rid::text,jsonb_build_object('reason',rsn,'product_id',p_product_id,'target',t));return rid;end$$;
create or replace function admin_set_product_featured(p_product_id uuid,p_featured boolean,p_rank int,p_reason text) returns boolean language plpgsql security definer set search_path=public as $$declare u app_users%rowtype;rsn text:=upper(btrim(coalesce(p_reason,'')));begin select * into u from app_users where auth_user_id=auth.uid() and active=true;if u.id is null or u.role not in('owner','admin')then raise exception 'OWNER OR ADMIN REQUIRED';end if;if p_product_id is null or not exists(select 1 from catalog_items where id=p_product_id and active=true)then raise exception 'ACTIVE PRODUCT REQUIRED';end if;if length(rsn)<3 or length(rsn)>500 then raise exception 'CHANGE REASON MUST BE 3 TO 500 CHARACTERS';end if;if p_rank is not null and(p_rank<0 or p_rank>100000)then raise exception 'INVALID FEATURED RANK';end if;insert into product_popularity(product_id,manual_featured,manual_rank)values(p_product_id,coalesce(p_featured,false),case when coalesce(p_featured,false) then p_rank else null end)on conflict(product_id)do update set manual_featured=excluded.manual_featured,manual_rank=excluded.manual_rank,updated_at=now();insert into audit_log(actor_id,action,entity_type,entity_id,details)values(u.id,'PRODUCT_FEATURED_CHANGED','PRODUCT',p_product_id::text,jsonb_build_object('featured',coalesce(p_featured,false),'rank',case when coalesce(p_featured,false) then p_rank else null end,'reason',rsn));return true;end$$;
revoke all on function public_active_product_promotions(text),public_popular_products(int),admin_save_product_promotion(uuid,uuid,text,text,text,text,boolean,timestamptz,timestamptz,int,text),admin_set_product_featured(uuid,boolean,int,text) from public;grant execute on function public_active_product_promotions(text),public_popular_products(int) to anon,authenticated;grant execute on function admin_save_product_promotion(uuid,uuid,text,text,text,text,boolean,timestamptz,timestamptz,int,text),admin_set_product_featured(uuid,boolean,int,text) to authenticated;
